class PrivateLotStrategiesAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        }

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_closes = RollingWindow[float](101)
        self.aapl_rsi = RelativeStrengthIndex(14)

        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data: Slice):
        spy_bar = data.Bars[self.spy] if data.Bars.ContainsKey(self.spy) else None
        aapl_bar = data.Bars[self.aapl] if data.Bars.ContainsKey(self.aapl) else None

        # Market-state values are updated whenever their own bars are available.
        if spy_bar is not None:
            self.spy_closes.Add(float(spy_bar.Close))

        if aapl_bar is not None:
            if self.aapl_previous_close is not None:
                if aapl_bar.Close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)
            self.aapl_previous_close = aapl_bar.Close

        # Skip all rule evaluation unless every subscribed ticker has today's bar.
        if not all(data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        # Do not trade until all rule-related history is fully formed.
        if not self.spy_closes.IsReady or not self.aapl_rsi.IsReady:
            return

        current_spy_close = self.spy_closes[0]
        previous_spy_close = self.spy_closes[1]

        current_spy_sma = sum(self.spy_closes[i] for i in range(100)) / 100.0
        previous_spy_sma = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0

        spy_crosses_above = (
            previous_spy_close <= previous_spy_sma
            and current_spy_close > current_spy_sma
        )
        spy_crosses_below = (
            previous_spy_close >= previous_spy_sma
            and current_spy_close < current_spy_sma
        )

        # Evaluate sells before buys.
        if self.strategy_a_shares > 0 and spy_crosses_below:
            self.MarketOrder(self.spy, -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(self.aapl, -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and spy_crosses_above:
            shares = int(
                float(self.Portfolio.TotalPortfolioValue) * 0.40 / current_spy_close
            )
            if shares > 0:
                self.MarketOrder(self.spy, shares)
                self.strategy_a_shares = shares

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            aapl_close = float(aapl_bar.Close)
            if self.Portfolio.Cash >= 20_000 and aapl_close > 0:
                shares = int(20_000 / aapl_close)
                if shares > 0:
                    self.MarketOrder(self.aapl, shares)
                    self.strategy_b_shares = shares
