class TwoSlotStrategySystem(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        }

        self.close_history = {ticker: RollingWindow[float](101) for ticker in self.symbols}
        self.previous_close = {ticker: None for ticker in self.symbols}

        self.spy_previous_sma = None
        self.aapl_red_streak = 0

        self.rsi_average_gain = None
        self.rsi_average_loss = None
        self.aapl_rsi = None

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data: Slice):
        if any(symbol not in data.Bars for symbol in self.symbols.values()):
            return

        closes = {
            ticker: float(data.Bars[symbol].Close)
            for ticker, symbol in self.symbols.items()
        }

        aapl_close = closes["AAPL"]
        previous_aapl_close = self.previous_close["AAPL"]

        if previous_aapl_close is not None:
            if aapl_close < previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        if previous_aapl_close is not None:
            change = aapl_close - previous_aapl_close
            gain = max(change, 0)
            loss = max(-change, 0)

            if self.rsi_average_gain is None:
                pass
            else:
                self.rsi_average_gain = (
                    (self.rsi_average_gain * 13) + gain
                ) / 14
                self.rsi_average_loss = (
                    (self.rsi_average_loss * 13) + loss
                ) / 14

                if self.rsi_average_loss == 0:
                    self.aapl_rsi = 100.0
                else:
                    rs = self.rsi_average_gain / self.rsi_average_loss
                    self.aapl_rsi = 100.0 - (100.0 / (1.0 + rs))

        for ticker, close in closes.items():
            self.close_history[ticker].Add(close)

        if self.rsi_average_gain is None and self.close_history["AAPL"].Count >= 15:
            gains = []
            losses = []
            for i in range(14, 0, -1):
                change = self.close_history["AAPL"][i - 1] - self.close_history["AAPL"][i]
                gains.append(max(change, 0))
                losses.append(max(-change, 0))

            self.rsi_average_gain = sum(gains) / 14
            self.rsi_average_loss = sum(losses) / 14

            if self.rsi_average_loss == 0:
                self.aapl_rsi = 100.0
            else:
                rs = self.rsi_average_gain / self.rsi_average_loss
                self.aapl_rsi = 100.0 - (100.0 / (1.0 + rs))

        if self.close_history["SPY"].Count < 101 or self.aapl_rsi is None:
            for ticker, close in closes.items():
                self.previous_close[ticker] = close
            return

        spy_close = closes["SPY"]
        spy_today_sma = sum(self.close_history["SPY"][i] for i in range(100)) / 100.0
        spy_yesterday_sma = sum(self.close_history["SPY"][i] for i in range(1, 101)) / 100.0
        spy_yesterday_close = self.close_history["SPY"][1]

        spy_crosses_above = (
            spy_yesterday_close <= spy_yesterday_sma
            and spy_close > spy_today_sma
        )
        spy_crosses_below = (
            spy_yesterday_close >= spy_yesterday_sma
            and spy_close < spy_today_sma
        )

        # Sells are evaluated before buys.
        if self.strategy_a_shares > 0 and spy_crosses_below:
            self.MarketOrder(self.symbols["SPY"], -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi > 60:
            self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and spy_crosses_above:
            target_value = 0.40 * float(self.Portfolio.TotalPortfolioValue)
            quantity = int(target_value // spy_close)
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.strategy_a_shares = quantity

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            if float(self.Portfolio.Cash) >= 20_000:
                quantity = int(20_000 // aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.symbols["AAPL"], quantity)
                    self.strategy_b_shares = quantity

        self.spy_previous_sma = spy_today_sma

        for ticker, close in closes.items():
            self.previous_close[ticker] = close
